    Alighieri.instance.api.crateApiSyncNow(addr: addr);

Future<void> addPeer({required String addr}) =>
    Alighieri.instance.api.crateApiAddPeer(addr: addr);

/// 立刻跑一轮 DHT 发现（网络页「重试」按钮）。
Future<void> retryDiscovery() =>
    Alighieri.instance.api.crateApiRetryDiscovery();

/// 把后台线程收到的 op 归约进本机视图。界面空闲时轮询即可。
Future<int> pump() => Alighieri.instance.api.crateApiPump();

Future<int> trimOplog({required int keep}) =>
    Alighieri.instance.api.crateApiTrimOplog(keep: keep);

Future<void> wipeAll() => Alighieri.instance.api.crateApiWipeAll();

/// 尚未封装成语义方法的操作走这里（kind 用 `novel.put` 这类字面量）
Future<String> submitRaw({
  required String kind,
  required String key,
  required String bodyJson,
}) => Alighieri.instance.api.crateApiSubmitRaw(
  kind: kind,
  key: key,
  bodyJson: bodyJson,
);

/// 启动时跑一遍：规范化载荷的金标准向量、许可证登记表。
/// 为空数组表示通过。涉及钱与签名的东西不该只能靠点界面来验证。
Future<List<String>> selfCheck() => Alighieri.instance.api.crateApiSelfCheck();

Future<int> nowMillis() => Alighieri.instance.api.crateApiNowMillis();

