      name.hashCode ^
      category.hashCode ^
      summary.hashCode ^
      allows.hashCode ^
      requires.hashCode ^
      forbids.hashCode ^
      commercial.hashCode ^
      derivatives.hashCode ^
      recommended.hashCode ^
      text.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is LicenseView &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          spdx == other.spdx &&
          key == other.key &&
          shortName == other.shortName &&
          name == other.name &&
          category == other.category &&
          summary == other.summary &&
          allows == other.allows &&
          requires == other.requires &&
          forbids == other.forbids &&
          commercial == other.commercial &&
          derivatives == other.derivatives &&
          recommended == other.recommended &&
          text == other.text;
}

